import{_ as t,c as n,o as s,j as e,a as i}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"四庫全書序","description":"周易經傳集解 - 四庫全書序","frontmatter":{"title":"四庫全書序","description":"周易經傳集解 - 四庫全書序"},"headers":[],"relativePath":"classics/jingchuan-jijie/001.md","filePath":"classics/jingchuan-jijie/001.md"}'),l={name:"classics/jingchuan-jijie/001.md"};function r(c,a,o,p,d,u){return s(),n("div",null,[...a[0]||(a[0]=[e("p",null,"欽定四庫全書經部一",-1),e("h1",{id:"四庫全書序",tabindex:"-1"},[i("四庫全書序 "),e("a",{class:"header-anchor",href:"#四庫全書序","aria-label":"Permalink to “四庫全書序”"},"​")],-1),e("p",null,"易類提要",-1),e("p",null,"臣等謹案：",-1),e("p",null,"周易經傳集解三十六卷，宋林栗撰。栗字黃中，福清人。紹興十二年進士，官至兵部侍郎。與朱子論易及西銘不合，遂上疏論朱子。時太常博士葉適、侍御史胡晉臣皆助朱子劾栗，因罷知泉州，乂移明州。卒諡簡肅。事蹟具宋史本傳。是書淳熙十二年四月嘗進於朝，首列進書表、貼黃、敕諭各一道，栗自序一篇。貼黃稱本名周易爻象序雜指解，後以未能該舉彖詞、擊詞、文言說卦，乃改今名。王應麟玉海稱具書經傳三十二卷、系詞上下二卷、文言說卦序雜本文共一卷，河圖洛書八卦九疇大衍總會圖六十四卦立成圖大衍揲蓍解共一卷，與今本合。當時與朱子所爭者，今不可考。朱子語類中惟載論繋詞一條，謂栗以太極生兩儀，包四象，四象包八卦，與聖人所謂生者意思不同，其餘則無所排斥。朱彝尊經義考引董真卿之言，謂其說每卦必兼互體、約象、覆卦為太泥。時楊敬仲有易論，黃中有易解，或曰：「黃中文字可毀。」朱子曰：「卻是楊敬仲文字可毀。」是朱子並不欲廢其書。考陳振孫書錄解題曰：「其與朱侍講有違言，以論易不合。」今以事理推之，於時朱子負盛名，駸駸向用，而栗之登第在朱子前七年，既以前輩自居，又朱子方除兵部郎中，而栗為兵部侍郎，正其所屬，詞色相軋，兩不肯下，遂互激而成訐奏。蓋其釁始於論易，而其故不全由於論易，故振孫云然。後人以朱子之故，遂廢栗書，似非朱子之意矣。經義考又曰：「福清林黃中、金華唐與政，皆博通經學，而一糾朱子，一為朱子所糾，其所著經說，學者遂置而不問，與政之書無復存者。黃中雖有易解，而流傳未廣，恐後泯沒。然當黃中既歿，勉齊黃氏為文祭之，其略曰：嗟哉我公，受天勁氣，為時直臣。玩羲經之爻象，究筆削於獲麟。至其立朝正色，苟咈吾意，雖當世大儒，或見排斥；苟異吾趨，雖前賢篤論，亦不樂於因循。規公之過，而公之近仁者，抑可見矣。論者固不以一𤯝而掩其大醇也。勉齋為文公高弟，而好惡之公、推許之至若是，然則黃中之易，其可不傳鈔乎？」持論頗為平允。昔劉安世與伊川程子各為一代偉人，其元城語錄、盡言集亦不以嘗劾程子而廢。耿南仲媚敵誤國，易祓依附權奸，其所撰易解，今亦並行。栗雖不得比安世，視南仲與祓則有間矣。故仍錄其書，而並存「彝尊」之論焉。乾隆四十六年九月恭校上。",-1),e("p",null,"總纂官臣紀呁、臣陸錫熊、臣孫士毅，總校官臣陸費墀。",-1)])])}const _=t(l,[["render",r]]);export{m as __pageData,_ as default};
